head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    c.disableDate('*');
};
scwin.trigger2_onclick = function(e) {
    c.enableDate('20180812');
};
scwin.trigger3_onclick = function(e) {
    c.enableDate('*');
};
scwin.trigger4_onclick = function(e) {
    c.disableDate('20180812 20180811');
};
scwin.trigger5_onclick = function(e) {
    ic.disableDate('*');
};
scwin.trigger6_onclick = function(e) {
    ic.enableDate('20180812');
};
scwin.trigger7_onclick = function(e) {
    ic.enableDate('*');
};
scwin.trigger8_onclick = function(e) {
    ic.disableDate('20180812 20180811');
};
scwin.rgb2hex = function(rgb) {
    rgb = rgb.match(/^rgba?[\s+]?\([\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?/i);
    return (rgb && rgb.length === 4) ? "#" +
        ("0" + parseInt(rgb[1], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[2], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[3], 10).toString(16)).slice(-2) : '';
}
scwin._checkRgb = function(id, hexa) {
    var rgb = WebSquare.wUnit.getJq("#" + id).css("color");
    var color;
    if (rgb.indexOf("rgb") != -1) {
        color = scwin.rgb2hex(rgb);
        return color == hexa;
    }
    return rgb == hexa;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //pc
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('c_selectbox_year_button').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('c_selectbox_year_itemTable_40').click()");
    //WebSquare.wUnit.addCommand("pause", "500");     
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('c_selectbox_month_button').click()");
    //WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('c_selectbox_month_itemTable_7').click()");
    //WebSquare.wUnit.addCommand("pause", "500");     
    //mobile
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('c').gotoYear(2018)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('c').gotoMonth(8)");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin._checkRgb('c_cell_2_0', '#000000')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin._checkRgb('c_cell_2_0', '#d02121')", "true");
